cd /Users/serro/Documents/dev/n/nucleus && set -e && \
mv client/application/shell client/shell && echo "moved shell" && \
grep -rl --include='*.ts' --include='*.tsx' --include='*.js' --include='*.mjs' --include='*.svelte' --include='*.json' --exclude-dir=node_modules --exclude-dir=.git --exclude-dir=.svelte-kit '@nucleum/application/shell' apps client extensions services shared schema tests tools | tr '\n' '\0' | xargs -0 sed -i '' 's|@nucleum/application/shell|@nucleum/shell|g' && echo "rewrote specifiers" && \
sed -i '' 's|"client/application",|"client/application",\n    "client/shell",|' package.json && \
sed -i '' 's|"@nucleum/application": "client/application"|"@nucleum/application": "client/application",\n  "@nucleum/shell": "client/shell"|' tools/alias-map.json && \
node -e '
const fs = require("fs");
for (const [file, prefix] of [["tsconfig.json", "./client/application"], ["client/tsconfig.json", "./application"]]) {
  let text = fs.readFileSync(file, "utf8");
  const marker = `"@nucleum/application/*": [`;
  const start = text.indexOf(`"@nucleum/application": [`);
  const end = text.indexOf("]", text.indexOf(marker)) + 1;
  const block = text.slice(start, end);
  const shellBlock = block
    .split("@nucleum/application").join("@nucleum/shell")
    .split(prefix).join(prefix.replace(/application$/, "shell"));
  text = text.slice(0, end) + ",\n" + shellBlock + text.slice(end);
  fs.writeFileSync(file, text);
  console.log("patched", file);
}
' && \
echo "=== leftover application/shell refs (expect none) ===" && \
{ grep -rn --include='*.ts' --include='*.svelte' --include='*.json' --include='*.mjs' --exclude-dir=node_modules --exclude-dir=.svelte-kit 'application/shell' apps client extensions services tools tests | grep -v 'client-boundaries\|README' || echo "  NONE"; }

