const fs = require("fs");
const demote = (file, names) => {
  const pkg = JSON.parse(fs.readFileSync(file, "utf8"));
  for (const name of names) {
    if (pkg.dependencies?.[name]) {
      delete pkg.dependencies[name];
      pkg.peerDependencies = { ...(pkg.peerDependencies || {}), [name]: "*" };
